      "idea": "",
      "trap": "Пытаться обнулять элементы случайным образом в разброс. Запомните строгий порядок: сначала полностью обнуляем 1-й столбец под диагональю, затем закрываем 1-ю строку и обнуляем 2-й столбец, и так далее слева направо!",
