      "idea": "Если бы в ступенчатом виде матрицы была нулевая строка, то при умножении на любую матрицу справа эта строка так и осталась бы нулём, и получить единицу на главной диагонали единичной матрицы E было бы физически невозможно.",
      "trap": "",
      "theoryLinks": [],
      "sections": {
        "intro": "<p><strong>Нужные определения.</strong> $A\\in M_{m\\times n}$ обратима справа, если $\\exists B$: $AB=E_m$. $\\bar A=PA$ — ступенчатый вид $A$, $P$ — произведение элементарных матриц (обратима).</p>",
        "Формулировка": "<p>Если $A$ обратима справа, то в её ступенчатом виде $\\bar A$ нет нулевых строк.</p>",
        "Доказательство": "<p><strong>Лемма.</strong> Если у матрицы $M$ строка с номером $i$ нулевая, то у $MX$ строка $i$ нулевая для любой $X$. Действительно, $(MX)_{ij}=\\sum_s m_{is}x_{sj}=\\sum_s 0\\cdot x_{sj}=0$. Следовательно, $MX\\neq E$ (у $E$ на месте $(i,i)$ стоит $1$).</p>\n<p><strong>Доказательство от противного.</strong> Пусть $AB=E$, но $\\bar A=PA$ имеет нулевую строку. Рассмотрим матрицу $X=BP^{-1}$:</p>\n<p>$$\\bar AX=(PA)(BP^{-1})=P(AB)P^{-1}=PEP^{-1}=PP^{-1}=E.$$</p>\n<p>Но по лемме $\\bar AX\\neq E$, так как у $\\bar A$ есть нулевая строка. Противоречие. Значит, нулевых строк в $\\bar A$ нет. $\\blacksquare$</p>",
        "Замечания": "<ul>\n<li>Схема от противного: допускаем «обратима справа» и «есть нулевая строка», получаем одновременно $\\bar AX=E$ и $\\bar AX\\neq E$.</li>\n<li>Практическое следствие: если при методе Гаусса слева появилась нулевая строка — обратной матрицы нет.</li>\n</ul>"
      }
