      "trap": "Каждое преобразование строк (включая перестановку!) нужно делать через всю строку, за черту тоже. Переставите строки только слева — получите неверный ответ!",
      "theoryLinks": [],
      "sections": {
        "Формулировка": "<p>Пусть $A\\in M_n(\\mathbb R)$. Запишем матрицу $(A\\mid E)$ размера $n\\times2n$ и будем применять элементарные преобразования строк.</p>\n<ol>\n<li>Если при приведении левой части к ступенчатому виду появилась нулевая строка, то $A$ необратима.</li>\n<li>Иначе левую часть можно привести к $E$, и тогда справа окажется $A^{-1}$:</li>\n</ol>\n<p>$$(A\\mid E)\\sim(E\\mid A^{-1}),\\qquad A^{-1}=QSP.$$</p>",
        "Доказательство": "<p>Элементарное преобразование строк матрицы $(A\\mid E)$ — это умножение слева на элементарную матрицу $P_i$, причём $P_i(A\\mid E)=(P_iA\\mid P_iE)$: одна и та же $P_i$ действует на обе половины.</p>\n<ol>\n<li>Пусть ступенчатый вид $PA$ содержит нулевую строку. Если бы $A$ была обратима, то $A$ была бы обратима справа и по теореме о нулевых строках в $PA$ их бы не было. Противоречие. Значит, $A$ необратима.</li>\n</ol>\n<ol>\n<li>Пусть нулевых строк нет. Как в теореме об односторонней обратимости, $PA$ верхнетреугольная с ненулевой диагональю; обратным ходом (матрица $S$) и делением строк на диагональные элементы (матрица $Q$) получаем $QSPA=E$. Обозначим $T=QSP$. Тогда $TA=E$, и так как $A$ квадратна, $T=A^{-1}$. Применив те же преобразования ко всей матрице:</li>\n</ol>\n<p>$$T(A\\mid E)=(TA\\mid TE)=(E\\mid T)=(E\\mid A^{-1}).\\ \\blacksquare$$</p>",
        "Замечания": "<ul>\n<li>Правая половина «записывает» произведение всех сделанных преобразований. Поэтому <strong>каждое</strong> преобразование — перестановку строк в том числе — применяют к <strong>всей</strong> строке, через черту. Переставить строки только слева — значит получить $A^{-1}$ с переставленными столбцами.</li>\n<li>Пример: $A=\\begin{pmatrix}1&1&1\\\\0&2&2\\\\1&0&1\\end{pmatrix}$, $A^{-1}=\\begin{pmatrix}1&-\\frac12&0\\\\1&0&-1\\\\-1&\\frac12&1\\end{pmatrix}$.</li>\n<li>Пример необратимой: $\\begin{pmatrix}0&1&1\\\\1&1&1\\\\2&1&1\\end{pmatrix}$ — после $R_1\\leftrightarrow R_2$, $R_3-2R_1$, $R_3+R_2$ получается нулевая строка $(0\\ 0\\ 0\\mid 1\\ {-2}\\ 1)$.</li>\n</ul>"
      }
