      "idea": "Модуль |z| — это длина радиус-вектора на плоскости по теореме Пифагора √(a² + b²). Для него выполняется классическое геометрическое неравенство треугольника: третья сторона треугольника |z₁ + z₂| не превосходит суммы длин двух других сторон |z₁| + |z₂|.",
      "trap": "",
      "theoryLinks": [],
      "sections": {
        "intro": "<p><strong>Нужные определения.</strong> $z=a+bi$, $|z|=\\sqrt{a^2+b^2}$ — длина вектора $(a,b)$.</p>",
        "Формулировка": "<ol>\n<li>$|z|=\\sqrt{z\\bar z}$, то есть $|z|^2=z\\bar z$; при $z\\neq0$: $z^{-1}=\\dfrac{\\bar z}{|z|^2}$;</li>\n<li>$|z|=0\\iff z=0$;</li>\n<li>$|z|=|-z|$;</li>\n<li>$|z|=|\\bar z|$.</li>\n</ol>",
        "Доказательство": "<ol>\n<li>$z\\bar z=(a+bi)(a-bi)=a^2+b^2$ (свойство сопряжения), значит $|z|^2=a^2+b^2=z\\bar z$. Отсюда при $z\\neq0$: $z\\cdot\\dfrac{\\bar z}{|z|^2}=\\dfrac{z\\bar z}{z\\bar z}=1$.</li>\n<li>(⇒) $|z|=0\\Rightarrow a^2+b^2=0$. Сумма неотрицательных чисел равна нулю, только если оба равны нулю: $a=b=0$, то есть $z=0$. (⇐) $z=0\\Rightarrow a=b=0\\Rightarrow|z|=\\sqrt0=0$.</li>\n<li>$-z=-a-bi$, $|-z|=\\sqrt{(-a)^2+(-b)^2}=\\sqrt{a^2+b^2}=|z|$.</li>\n<li>$\\bar z=a-bi$, $|\\bar z|=\\sqrt{a^2+(-b)^2}=\\sqrt{a^2+b^2}=|z|$. $\\blacksquare$</li>\n</ol>",
        "Замечания": "<ul>\n<li>Геометрически: $-z$ — поворот вектора $z$ на $\\pi$ (аргумент $\\varphi+\\pi$), $\\bar z$ — отражение относительно $Ox$ (аргумент $-\\varphi$); длина не меняется.</li>\n<li>$|\\cos\\alpha+i\\sin\\alpha|=\\sqrt{\\cos^2\\alpha+\\sin^2\\alpha}=1$.</li>\n</ul>"
      }
