        "Доказательство": "<p>По свойству модуля $z^{-1}=\\dfrac{\\bar z}{z\\bar z}=\\dfrac{\\bar z}{r^2}$. Так как $a=r\\cos\\varphi$, $b=r\\sin\\varphi$:</p>\n<p>$$\\bar z=a-bi=r(\\cos\\varphi-i\\sin\\varphi).$$</p>\n<p>Тогда</p>\n<p>$$z^{-1}=\\frac{r(\\cos\\varphi-i\\sin\\varphi)}{r^2}=\\frac1r(\\cos\\varphi-i\\sin\\varphi)=\\frac1r\\big(\\cos(-\\varphi)+i\\sin(-\\varphi)\\big),$$</p>\n<p>так как $\\cos(-\\varphi)=\\cos\\varphi$, $\\sin(-\\varphi)=-\\sin\\varphi$. $\\blacksquare$</p>",
