      "trap": "",
      "theoryLinks": [],
      "sections": {
        "intro": "<p><strong>Нужные определения.</strong> $\\mathbb R^n=\\underbrace{\\mathbb R\\times\\ldots\\times\\mathbb R}_{n}=\\{(x_1,\\ldots,x_n)\\mid x_i\\in\\mathbb R\\}$. <strong>Арифметическим векторным пространством</strong> над $\\mathbb R$ называется множество матриц размера $1\\times n$ (или $n\\times1$) с операциями сложения матриц и умножения на число из $\\mathbb R$:</p>\n<p>$$x+y=(x_1+y_1,\\ldots,x_n+y_n),\\qquad\\lambda x=(\\lambda x_1,\\ldots,\\lambda x_n),\\qquad\\bar0=(0,\\ldots,0).$$</p>",
        "Формулировка": "<p>Для любых $x,y,z\\in\\mathbb R^n$, $\\lambda,\\mu\\in\\mathbb R$:</p>\n<ol>\n<li>$x+y=y+x$;</li>\n<li>$x+(y+z)=(x+y)+z$;</li>\n<li>$x+\\bar0=x$;</li>\n<li>существует $y$ с $x+y=\\bar0$, а именно $y=-x=(-1)x$;</li>\n<li>$\\lambda(x+y)=\\lambda x+\\lambda y$;</li>\n<li>$(\\lambda+\\mu)x=\\lambda x+\\mu x$;</li>\n<li>$(\\lambda\\mu)x=\\lambda(\\mu x)$;</li>\n<li>$1\\cdot x=x$.</li>\n</ol>",
        "Доказательство": "<p>Векторы из $\\mathbb R^n$ — это матрицы $1\\times n$, а операции — сложение матриц и умножение матрицы на число. Все восемь свойств — частный случай свойств сложения матриц и умножения на число (они доказываются покомпонентно из свойств вещественных чисел). Например, для п. 4: $x+(-1)x=(x_1-x_1,\\ldots,x_n-x_n)=\\bar0$; для п. 6: $((\\lambda+\\mu)x)_i=(\\lambda+\\mu)x_i=\\lambda x_i+\\mu x_i=(\\lambda x+\\mu x)_i$. $\\blacksquare$</p>",
        "Замечания": "<ul>\n<li>СЛАУ в векторной форме: $x_1A^{(1)}+\\ldots+x_nA^{(n)}=b$, где $A^{(j)}$ — столбцы матрицы системы; система $Ax=b$ совместна, если $b$ — линейная комбинация столбцов $A$.</li>\n</ul>"
      }
