      "trap": "",
      "theoryLinks": [],
      "sections": {
        "intro": "<p><strong>Нужные определения.</strong> Система векторов $\\{a_1,\\ldots,a_n\\}$ <strong>линейно зависима</strong>, если существуют $\\lambda_1,\\ldots,\\lambda_n\\in\\mathbb R$, не все равные нулю ($\\lambda_1^2+\\ldots+\\lambda_n^2\\neq0$), такие что $\\lambda_1a_1+\\ldots+\\lambda_na_n=\\bar0$. Иначе — <strong>линейно независима</strong>: $\\lambda_1a_1+\\ldots+\\lambda_na_n=\\bar0$ возможно только при $\\lambda_1=\\ldots=\\lambda_n=0$.</p>",
        "Формулировка": "<ol>\n<li>Система из одного вектора $\\{a\\}$ линейно зависима тогда и только тогда, когда $a=\\bar0$.</li>\n<li>Система, содержащая линейно зависимую подсистему, сама линейно зависима.</li>\n</ol>",
        "Доказательство": "<ol>\n<li>(⇐) Если $a=\\bar0$, то $1\\cdot a=\\bar0$ — нетривиальная комбинация ($\\lambda=1\\neq0$), система зависима.</li>\n</ol>\n<p>(⇒) Пусть $\\lambda a=\\bar0$ при $\\lambda\\neq0$. Умножим на $\\frac1\\lambda$: $a=\\frac1\\lambda\\bar0=\\bar0$.</p>\n<ol>\n<li>Пусть подсистема $\\{a_1,\\ldots,a_n\\}$ системы $\\{a_1,\\ldots,a_n,b_1,\\ldots,b_m\\}$ линейно зависима: $\\lambda_1a_1+\\ldots+\\lambda_na_n=\\bar0$, где $\\lambda_1^2+\\ldots+\\lambda_n^2\\neq0$. Положим $\\mu_1=\\ldots=\\mu_m=0$. Тогда</li>\n</ol>\n<p>$$\\lambda_1a_1+\\ldots+\\lambda_na_n+\\mu_1b_1+\\ldots+\\mu_mb_m=\\bar0,$$</p>\n<p>и набор $(\\lambda_1,\\ldots,\\lambda_n,\\mu_1,\\ldots,\\mu_m)$ нетривиален: $\\lambda_1^2+\\ldots+\\lambda_n^2+\\mu_1^2+\\ldots+\\mu_m^2\\neq0$. Значит, вся система линейно зависима. $\\blacksquare$</p>",
        "Замечания": "<ul>\n<li>Следствия: система, содержащая $\\bar0$, зависима; система с двумя одинаковыми векторами зависима: $1\\cdot a+(-1)\\cdot a=\\bar0$.</li>\n<li>Примеры: $(1,2)$ и $(2,4)$ зависимы: $(-2)(1,2)+1\\cdot(2,4)=\\bar0$. $(1,2)$ и $(1,1)$ независимы: из $\\lambda_1+\\lambda_2=0$, $2\\lambda_1+\\lambda_2=0$ следует $\\lambda_1=\\lambda_2=0$. $(1,0),(1,1),(0,1)$ зависимы: $(-1)(1,0)+1\\cdot(1,1)+(-1)(0,1)=\\bar0$.</li>\n<li>Частая ошибка: «не все $\\lambda_i$ равны нулю» — это <strong>не</strong> «$\\lambda_1\\lambda_2\\cdots\\lambda_n\\neq0$».</li>\n</ul>"
      }
