        "Формулировка": "<p>Если система $\\{a_1,\\ldots,a_n\\}$ линейно независима, а $\\{a_1,\\ldots,a_n,b\\}$ линейно зависима, то $b$ линейно выражается через $a_1,\\ldots,a_n$.</p>",
        "Доказательство": "<p>Так как $\\{a_1,\\ldots,a_n,b\\}$ зависима, существует нетривиальный набор $(\\lambda_1,\\ldots,\\lambda_n,\\mu)$ с</p>\n<p>$$\\lambda_1a_1+\\ldots+\\lambda_na_n+\\mu b=\\bar0.$$</p>\n<p>Покажем, что $\\mu\\neq0$. Пусть $\\mu=0$. Тогда $\\lambda_1a_1+\\ldots+\\lambda_na_n=\\bar0$, и так как $\\{a_1,\\ldots,a_n\\}$ независима, $\\lambda_1=\\ldots=\\lambda_n=0$. Тогда весь набор $(\\lambda_1,\\ldots,\\lambda_n,\\mu)$ нулевой — противоречие с его нетривиальностью.</p>\n<p>Итак, $\\mu\\neq0$; разделим на $\\mu$ и выразим $b$:</p>\n<p>$$b=-\\frac{\\lambda_1}{\\mu}a_1-\\frac{\\lambda_2}{\\mu}a_2-\\ldots-\\frac{\\lambda_n}{\\mu}a_n.\\ \\blacksquare$$</p>",
