        "Доказательство": "<p><strong>(⇒)</strong> Пусть система зависима: $\\lambda_1a_1+\\ldots+\\lambda_ka_k=\\bar0$, и не все $\\lambda_j$ равны нулю. Пусть $\\lambda_i\\neq0$. Разделим равенство на $\\lambda_i$:</p>\n<p>$$\\frac{\\lambda_1}{\\lambda_i}a_1+\\ldots+1\\cdot a_i+\\ldots+\\frac{\\lambda_k}{\\lambda_i}a_k=\\bar0,$$</p>\n<p>и перенесём все слагаемые, кроме $a_i$, вправо:</p>\n<p>$$a_i=-\\sum_{j\\neq i}\\frac{\\lambda_j}{\\lambda_i}a_j.$$</p>\n<p>Значит, $a_i$ — линейная комбинация остальных.</p>\n<p><strong>(⇐)</strong> Пусть $a_i=\\mu_1a_1+\\ldots+\\mu_{i-1}a_{i-1}+\\mu_{i+1}a_{i+1}+\\ldots+\\mu_ka_k$. Перенесём $a_i$ вправо:</p>\n<p>$$\\mu_1a_1+\\ldots+\\mu_{i-1}a_{i-1}+(-1)a_i+\\mu_{i+1}a_{i+1}+\\ldots+\\mu_ka_k=\\bar0.$$</p>\n<p>Набор коэффициентов нетривиален, так как коэффициент при $a_i$ равен $-1\\neq0$. Значит, система линейно зависима. $\\blacksquare$</p>",
