      "trap": "Студенты часто доказывают только одну сторону (⇒), забывая, что формулировка «тогда и только тогда» требует доказательства и достаточности (⇐).",
      "theoryLinks": [],
      "sections": {
        "intro": "<p><strong>Нужные определения.</strong> Система $\\{e_1,\\ldots,e_n\\}\\subseteq V$ — <strong>базис</strong> $V$, если она линейно независима и любой $a\\in V$ линейно выражается через неё: $a=\\lambda_1e_1+\\ldots+\\lambda_ne_n$; числа $(\\lambda_1,\\ldots,\\lambda_n)$ — <strong>координаты</strong> $a$ в базисе. Система <strong>максимальная линейно независимая</strong> в $V$, если она линейно независима и для любого $a\\in V$ система $\\{e_1,\\ldots,e_n,a\\}$ линейно зависима.</p>",
        "Формулировка": "<p>Система $\\{e_1,\\ldots,e_n\\}\\subseteq V$ является базисом $V$ тогда и только тогда, когда она — максимальная линейно независимая система в $V$.</p>",
        "Доказательство": "<p><strong>(⇒)</strong> Пусть $\\{e_1,\\ldots,e_n\\}$ — базис. Она линейно независима по определению. Возьмём любой $a\\in V$. Он выражается через базис: $a=\\lambda_1e_1+\\ldots+\\lambda_ne_n$. Значит, в системе $\\{e_1,\\ldots,e_n,a\\}$ вектор $a$ выражается через остальные, и по критерию линейной зависимости она линейно зависима. Итак, система максимальная линейно независимая.</p>\n<p><strong>(⇐)</strong> Пусть $\\{e_1,\\ldots,e_n\\}$ — максимальная линейно независимая. Она линейно независима. Для любого $a\\in V$ система $\\{e_1,\\ldots,e_n,a\\}$ линейно зависима, а $\\{e_1,\\ldots,e_n\\}$ независима, поэтому по свойству «добавили вектор — стала зависимой» $a$ выражается через $e_1,\\ldots,e_n$. Так как $a$ произвольный, $\\{e_1,\\ldots,e_n\\}$ — базис. $\\blacksquare$</p>",
        "Замечания": "<ul>\n<li><strong>Стандартный базис</strong> $\\mathbb R^n$: $e_1=(1,0,\\ldots,0)$, …, $e_n=(0,\\ldots,0,1)$. Он линейно независим, и $a=(x_1,\\ldots,x_n)=x_1e_1+\\ldots+x_ne_n$; например, $(5,-1,2)=5e_1-e_2+2e_3$.</li>\n<li>Координаты в базисе определены однозначно: если $a=\\sum\\lambda_ie_i=\\sum\\mu_ie_i$, то $\\sum(\\lambda_i-\\mu_i)e_i=\\bar0$, и из независимости $\\lambda_i=\\mu_i$.</li>\n</ul>"
      }
