        "Доказательство": "<ol>\n<li>Если $\\{a_1,\\ldots,a_m\\}$ максимальна в $X$ (добавление любого вектора из $X$ делает её зависимой), то она — базис $X$ (базис = максимальная линейно независимая система).</li>\n<li>Иначе найдётся $a_{m+1}\\in X$, такой что $\\{a_1,\\ldots,a_m,a_{m+1}\\}$ линейно независима. Повторяем рассуждение для новой системы.</li>\n</ol>\n<p>После $k$ шагов получаем линейно независимую систему $\\{a_1,\\ldots,a_{m+k}\\}\\subseteq X\\subseteq\\mathbb R^n$. Каждый её вектор выражается через стандартный базис $e_1,\\ldots,e_n$, поэтому по основной лемме о линейной зависимости</p>\n<p>$$m+k\\le n.$$</p>\n<p>Значит, процесс не может продолжаться бесконечно: при некотором $k$ система станет максимальной, то есть базисом $X$. $\\blacksquare$</p>",
