      "idea": "Ранг системы векторов равен числу независимых осей, которые они натягивают (размерности линейной оболочки).",
      "trap": "Ранг не зависит от того, сколько нулей или дубликатов векторов вы допишете в систему.",
      "theoryLinks": [],
      "sections": {
        "intro": "<p><strong>Нужные определения.</strong> <strong>Ранг</strong> $\\operatorname{rank}X$ конечного набора $X$ — число векторов в базисе $X$ (в максимальной линейно независимой подсистеме); <strong>размерность</strong> $\\dim$ — то же для множества (пространства), $\\dim\\mathbb R^n=n$. <strong>Линейная оболочка</strong> $\\langle X\\rangle$ — множество всех линейных комбинаций векторов из $X$. <strong>Подпространство</strong> $U\\subseteq\\mathbb R^n$ — подмножество, замкнутое относительно сложения и умножения на число.</p>",
        "Формулировка": "<ol>\n<li>Для конечного набора $X\\subseteq\\mathbb R^n$: $\\dim\\langle X\\rangle=\\operatorname{rank}X$.</li>\n<li>Если $\\operatorname{rank}X=r$ и $\\{a_1,\\ldots,a_r\\}\\subseteq X$ линейно <strong>независима</strong>, то это базис $X$.</li>\n</ol>",
        "Доказательство": "<ol>\n<li>Пусть $\\{a_1,\\ldots,a_r\\}$ — базис $X$, $r=\\operatorname{rank}X$. Покажем, что это и базис $\\langle X\\rangle$. Независимость есть. Каждый вектор из $X$ выражается через $a_1,\\ldots,a_r$; любой $v\\in\\langle X\\rangle$ — линейная комбинация векторов из $X$, а значит (подставив их выражения) линейная комбинация $a_1,\\ldots,a_r$. Итак, $\\{a_1,\\ldots,a_r\\}$ — базис $\\langle X\\rangle$, и $\\dim\\langle X\\rangle=r$.</li>\n</ol>\n<ol>\n<li>Дополним $\\{a_1,\\ldots,a_r\\}$ векторами из $X$ до базиса $X$. В любом базисе $X$ ровно $r$ векторов (все базисы равномощны), а в нашей системе уже $r$ векторов. Значит, добавлять нечего, и $\\{a_1,\\ldots,a_r\\}$ — базис $X$. $\\blacksquare$</li>\n</ol>",
        "Замечания": "<ul>\n<li>Примеры подпространств: $U_1=\\{(\\lambda,0)\\mid\\lambda\\in\\mathbb R\\}\\subseteq\\mathbb R^2$ — подпространство; $U_2=\\{(k,0)\\mid k\\in\\mathbb N\\}$ — нет: $\\frac32(1,0)\\notin U_2$.</li>\n<li>$\\langle(1,0),(1,1)\\rangle=\\mathbb R^2$, размерность $2$; $\\langle(1,1),(2,2)\\rangle=\\{(\\lambda,\\lambda)\\mid\\lambda\\in\\mathbb R\\}$, размерность $1$.</li>\n<li>Частая ошибка в формулировке п. 2: нужна <strong>независимая</strong>, а не «зависимая» система.</li>\n</ul>"
      }
