      "idea": "Операции метода Гаусса над строками не меняют ни строчный ранг (строки обратимо комбинируются), ни столбцовый (множество решений $Ax=0$ остаётся прежним). В ступенчатом виде оба ранга очевидно равны числу ступенек.",
      "trap": "Никогда не пытайтесь искать ранг прямоугольной матрицы через определитель: определителя у неквадратных матриц не существует!",
      "theoryLinks": [],
      "sections": {
        "intro": "<p><strong>Нужные определения.</strong> Для $A\\in M_{m\\times n}(\\mathbb R)$: $A_{(1)},\\ldots,A_{(m)}\\in\\mathbb R^n$ — строки, $A^{(1)},\\ldots,A^{(n)}\\in\\mathbb R^m$ — столбцы. $\\operatorname{rank}_{\\text{стр}}A=\\operatorname{rank}\\{A_{(1)},\\ldots,A_{(m)}\\}$, $\\operatorname{rank}_{\\text{стлб}}A=\\operatorname{rank}\\{A^{(1)},\\ldots,A^{(n)}\\}$.</p>",
        "Формулировка": "<p>$\\operatorname{rank}_{\\text{стр}}A=\\operatorname{rank}_{\\text{стлб}}A$. Это общее число называется <strong>рангом матрицы</strong> $\\operatorname{rank}A$.</p>",
        "Доказательство": "<p><strong>1. Элементарные преобразования строк не меняют ранг по строкам.</strong> Достаточно показать, что новая система строк и старая выражаются друг через друга: тогда их линейные оболочки совпадают, и по $\\dim\\langle X\\rangle=\\operatorname{rank}X$ ранги равны.</p>\n<ul>\n<li>$P_{st}$ — набор строк тот же, переставлен.</li>\n<li>$P_{st}(\\lambda)$: новая строка $A_{(s)}+\\lambda A_{(t)}$ выражается через старые; обратно $A_{(s)}=[A_{(s)}+\\lambda A_{(t)}]-\\lambda A_{(t)}$.</li>\n<li>$P_s(\\lambda)$, $\\lambda\\neq0$: новая $\\lambda A_{(s)}$, обратно $A_{(s)}=\\frac1\\lambda(\\lambda A_{(s)})$.</li>\n</ul>\n<p><strong>2. Элементарные преобразования строк не меняют ранг по столбцам.</strong> Пусть $\\hat A=PA$, $P$ обратима. Для столбца коэффициентов $\\lambda=(\\lambda_1,\\ldots,\\lambda_n)^T$:</p>\n<p>$$\\lambda_1A^{(1)}+\\ldots+\\lambda_nA^{(n)}=A\\lambda,$$</p>\n<p>и $A\\lambda=\\bar0\\iff PA\\lambda=\\bar0\\iff\\hat A\\lambda=\\bar0$. Значит, столбцы $A$ и $\\hat A$ с одинаковыми номерами связаны одинаковыми линейными зависимостями: подсистема столбцов $A$ независима тогда и только тогда, когда независима соответствующая подсистема столбцов $\\hat A$. Поэтому ранги по столбцам равны.</p>\n<p><strong>3. Для ступенчатой матрицы ранги равны.</strong> Пусть $\\hat A$ — ступенчатый вид, $r$ ненулевых строк. Ненулевые строки линейно независимы (в комбинации $\\sum\\mu_iA_{(i)}=\\bar0$ смотрим на столбец первой ступеньки: там ненулевой только элемент первой строки, значит $\\mu_1=0$; далее по очереди $\\mu_2=0$, …), поэтому $\\operatorname{rank}_{\\text{стр}}\\hat A=r$. Столбцы со ступеньками ($r$ штук) линейно независимы тем же рассуждением, а любой столбец лежит в подпространстве векторов с нулями в последних $m-r$ координатах, размерность которого $r$; значит, $\\operatorname{rank}_{\\text{стлб}}\\hat A=r$.</p>\n<p>Итого: $\\operatorname{rank}_{\\text{стр}}A=\\operatorname{rank}_{\\text{стр}}\\hat A=r=\\operatorname{rank}_{\\text{стлб}}\\hat A=\\operatorname{rank}_{\\text{стлб}}A$. $\\blacksquare$</p>",
        "Замечания": "<ul>\n<li>Практически: $\\operatorname{rank}A$ = число ненулевых строк в ступенчатом виде.</li>\n<li>В решении СЛАУ число главных неизвестных равно $\\operatorname{rank}A$, свободных $n-\\operatorname{rank}A$.</li>\n</ul>"
      }
